import{c as n,Q as a,j as p,m as t}from"./chunks/framework.DOi4mjdC.js";const d=JSON.parse('{"title":"创建算子工程","description":"","frontmatter":{},"headers":[{"level":1,"title":"创建算子工程","slug":"创建算子工程"}],"relativePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/创建算子工程.md","filePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/创建算子工程.md"}'),l={name:"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/创建算子工程.md"};function e(o,s,i,u,c,q){return a(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="创建算子工程" tabindex="-1">创建算子工程 <a class="header-anchor" href="#创建算子工程" aria-label="Permalink to &quot;创建算子工程&quot;">​</a></h1><p>CANN开发套件包中提供了自定义算子工程生成工具msOpGen，可基于算子原型定义输出算子工程：包括<strong>算子host侧代码实现文件</strong>、<strong>算子kernel侧实现文件</strong>以及<strong>工程编译配置文件等</strong>。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>使用msOpGen工具创建算子工程之前，需要参考<a href="./../../../../入门教程/环境准备.html">环境准备</a>章节安装驱动固件和CANN软件包，完成开发环境和运行环境的准备。</p></div><p>使用msOpGen工具创建算子开发工程的步骤如下：</p><ol><li><p>编写算子的原型定义json文件，用于生成算子开发工程。</p><p>例如，AddCustom算子的json文件命名为add_custom.json，文件内容如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;op&quot;: &quot;AddCustom&quot;,</span></span>
<span class="line"><span>        &quot;input_desc&quot;: [</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;x&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;format&quot;: [</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;</span></span>
<span class="line"><span>                ],</span></span>
<span class="line"><span>                &quot;type&quot;: [</span></span>
<span class="line"><span>                    &quot;float16&quot;,</span></span>
<span class="line"><span>                    &quot;float&quot;,</span></span>
<span class="line"><span>                    &quot;int32&quot;</span></span>
<span class="line"><span>                ]</span></span>
<span class="line"><span>            },</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;y&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;format&quot;: [</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;</span></span>
<span class="line"><span>                ],</span></span>
<span class="line"><span>                &quot;type&quot;: [</span></span>
<span class="line"><span>                    &quot;float16&quot;,</span></span>
<span class="line"><span>                    &quot;float&quot;,</span></span>
<span class="line"><span>                    &quot;int32&quot;</span></span>
<span class="line"><span>                ]</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        ],</span></span>
<span class="line"><span>        &quot;output_desc&quot;: [</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;z&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;format&quot;: [</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;,</span></span>
<span class="line"><span>                    &quot;ND&quot;</span></span>
<span class="line"><span>                ],</span></span>
<span class="line"><span>                &quot;type&quot;: [</span></span>
<span class="line"><span>                    &quot;float16&quot;,</span></span>
<span class="line"><span>                    &quot;float&quot;,</span></span>
<span class="line"><span>                    &quot;int32&quot;</span></span>
<span class="line"><span>                ]</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        ]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>例如，ReduceMaxCustom算子（包含属性）的json文件命名为reduce_max_custom.json，文件内容如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;op&quot;: &quot;ReduceMaxCustom&quot;,</span></span>
<span class="line"><span>         &quot;input_desc&quot;: [</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;x&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;format&quot;: [&quot;ND&quot;],</span></span>
<span class="line"><span>                &quot;type&quot;: [&quot;float16&quot;]</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        ],</span></span>
<span class="line"><span>        &quot;output_desc&quot;: [</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;y&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;format&quot;: [&quot;ND&quot;],</span></span>
<span class="line"><span>                &quot;type&quot;: [&quot;float16&quot;]</span></span>
<span class="line"><span>            },</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;idx&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;format&quot;: [&quot;ND&quot;],</span></span>
<span class="line"><span>                &quot;type&quot;: [&quot;int32&quot;]</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        ],</span></span>
<span class="line"><span>        &quot;attr&quot;: [                                                                   </span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;reduceDim&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;required&quot;,</span></span>
<span class="line"><span>                &quot;type&quot;: &quot;int&quot;</span></span>
<span class="line"><span>            },</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                &quot;name&quot;: &quot;isKeepDim&quot;,</span></span>
<span class="line"><span>                &quot;param_type&quot;: &quot;optional&quot;,</span></span>
<span class="line"><span>                &quot;type&quot;: &quot;int&quot;,</span></span>
<span class="line"><span>                &quot;default_value&quot;: 1</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        ]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>原型定义json文件中的算子类型字段op需要采用<strong>大驼峰</strong>的命名方式，即采用大写字符区分不同的语义。</p></div></li><li><p>使用msOpGen工具生成算子的开发工程。以生成AddCustom的算子工程为例，下文仅针对关键参数进行解释，详细参数说明请参见<a href="https://hiascend.com/document/redirect/CannCommercialToolOpDev" target="_blank" rel="noreferrer">《算子开发工具用户指南》</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>\${INSTALL_DIR}/python/site-packages/bin/msopgen gen -i $HOME/sample/add_custom.json -c ai_core-&lt;soc_version&gt; -lan cpp -out $HOME/sample/AddCustom</span></span></code></pre></div><ul><li><p>\${INSTALL_DIR}为CANN软件安装后文件存储路径，请根据实际环境进行替换。</p></li><li><p>-i：指定算子原型定义文件_add_custom_.json所在路径，请根据实际情况修改。</p></li><li><p>-c：ai_core-_&lt;soc_version&gt;<em>代表算子在AI Core上执行，</em>&lt;soc_version&gt;_为AI处理器的型号。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>针对如下产品：在安装AI处理器的服务器执行npu-smi info命令进行查询，获取Name信息。实际配置值为AscendName，例如Name取值为xxxyy，实际配置值为Ascendxxxyy。&lt;br/&gt;&lt;br/&gt; Atlas A2 训练系列产品/Atlas A2 推理系列产品<br> Atlas 200I/500 A2 推理产品<br> Atlas 推理系列产品<br> Atlas 训练系列产品&lt;br/&gt;&lt;br/&gt;</li><li>针对&lt;term&gt;Atlas A3 训练系列产品&lt;/term&gt;/&lt;term&gt;Atlas A3 推理系列产品&lt;/term&gt;，在安装AI处理器的服务器执行npu-smi info -t board -i id -c chip_id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。其中：&lt;br/&gt;id：设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。&lt;br/&gt; chip_id：芯片id，通过npu-smi info -m命令查出的Chip ID即为芯片id。&lt;br/&gt;&lt;br/&gt;</li><li>针对Ascend 950PR/Ascend 950DT，在安装AI处理器的服务器执行npu-smi info -t board -i id命令进行查询，获取Chip Name和NPU Name信息，实际配置值为Chip Name_NPU Name。例如Chip Name取值为Ascendxxx，NPU Name取值为1234，实际配置值为Ascendxxx_1234。&lt;br/&gt; 其中：id为设备id，通过npu-smi info -l命令查出的NPU ID即为设备id。</li></ul></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>基于同系列的AI处理器型号创建的算子工程，其基础功能（基于该工程进行算子开发、编译和部署）通用。</p></div></li><li><p>-lan： 参数cpp代表算子基于Ascend C编程框架，使用C/C++编程语言开发。</p></li><li><p>-out：生成文件所在路径，可配置为绝对路径或者相对路径，并且工具执行用户对路径具有可读写权限。若不配置，则默认生成在执行命令的当前路径。</p></li></ul></li><li><p>命令执行完后，会在-out指定目录或者默认路径下生成算子工程目录，工程中包含算子实现的模板文件，编译脚本等，以AddCustom算子为例，目录结构如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AddCustom</span></span>
<span class="line"><span>├── build.sh         // 编译入口脚本</span></span>
<span class="line"><span>├── cmake            // 算子工程编译所需脚本及公共编译文件存放目录</span></span>
<span class="line"><span>├── CMakeLists.txt    // 算子工程的CMakeLists.txt</span></span>
<span class="line"><span>├── CMakePresets.json    // 编译配置项</span></span>
<span class="line"><span>├── framework        // AI框架适配时，算子插件实现文件目录</span></span>
<span class="line"><span>├── op_host                      // host侧实现文件</span></span>
<span class="line"><span>│   ├── add_custom_tiling.h    // 算子tiling定义文件</span></span>
<span class="line"><span>│   ├── add_custom.cpp         // 算子原型注册、shape推导、信息库、tiling实现等内容文件</span></span>
<span class="line"><span>│   ├── CMakeLists.txt</span></span>
<span class="line"><span>├── op_kernel                   // kernel侧实现文件</span></span>
<span class="line"><span>│   ├── CMakeLists.txt   </span></span>
<span class="line"><span>│   ├── add_custom.cpp        // 算子代码实现文件 </span></span>
<span class="line"><span>└── scripts                     // 自定义算子工程打包相关脚本所在目录</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>上述目录结构中的粗体文件为后续算子开发过程中需要修改的文件，其他文件无需修改。</li><li>kernel侧实现依赖的所有文件需全部放置在op_kernel目录下，不遵循该约束会导致<a href="./算子包编译/算子工程编译.html#li139988411333">源码发布</a>场景在线编译失败。因为在后续的算子源码发布时，只会打包发布op_kernel目录下的文件。</li></ul></div></li></ol><p>工程目录中的op_kernel和op_host包含了算子的核心实现文件。op_kernel下存放<a href="./Kernel侧算子实现.html">kernel侧算子实现</a>。op_host下存放host侧代码实现，包括<a href="./算子原型定义.html">算子原型定义</a>、<a href="./Host侧Tiling实现/基本流程.html">host侧tiling实现</a>。其中kernel侧算子实现和host侧tiling实现在<a href="./../../../../算子实践参考/SIMD算子实现/概述.html">SIMD算子实现</a>章节已经介绍了其核心的实现方法，在该章节会侧重于介绍接入CANN框架后的编程模式和API的使用。工程目录中的CMakePresets.json，用于开发者完成工程编译相关配置，之后即可进行编译部署。</p>`,6)])])}const m=n(l,[["render",e]]);export{d as __pageData,m as default};
